class LlmClient:
    def __init__(self, models):
        self.models = models
        self.start = 0

    def generate(self, prompt):
        for i in range(self.start, len(self.models)):
            out = try_model(self.models[i], prompt)
            if out is not None:
                return out
            self.start = i + 1
        return None
